import sys


def esta_balanceada(expressao):
    """Verifica se os parênteses de uma expressão abrem e fecham na ordem correta."""
    pilha = []

    for caractere in expressao:
        if caractere == "(":
            # A abertura fica pendente até aparecer o fechamento correspondente.
            pilha.append(caractere)
        elif caractere == ")":
            # Fechar sem nenhuma abertura disponível invalida a expressão.
            if not pilha:
                return False
            pilha.pop()

    # Se ainda há itens na pilha, sobraram aberturas sem fechamento.
    return not pilha


# Cada linha da entrada é uma expressão; a leitura termina no fim do arquivo.
for linha in sys.stdin:
    expressao = linha.rstrip("\n")
    print("correct" if esta_balanceada(expressao) else "incorrect")

from collections import deque
import heapq
import sys


def classificar(operacoes):
    """Simula as três estruturas e classifica quais reproduzem as remoções."""
    pilha = []
    fila = deque()
    prioridade = []  # heapq é min-heap; valores negativos simulam uma max-heap.

    pode_ser_pilha = True
    pode_ser_fila = True
    pode_ser_prioridade = True

    for tipo, valor in operacoes:
        if tipo == 1:
            # Toda inserção é reproduzida nas candidatas que ainda são possíveis.
            if pode_ser_pilha:
                pilha.append(valor)
            if pode_ser_fila:
                fila.append(valor)
            if pode_ser_prioridade:
                heapq.heappush(prioridade, -valor)
            continue

        # Na remoção, o valor observado precisa ser exatamente o que a estrutura
        # candidata retiraria naquele momento.
        if pode_ser_pilha and (not pilha or pilha.pop() != valor):
            pode_ser_pilha = False
        if pode_ser_fila and (not fila or fila.popleft() != valor):
            pode_ser_fila = False
        if pode_ser_prioridade and (
            not prioridade or -heapq.heappop(prioridade) != valor
        ):
            pode_ser_prioridade = False

    candidatas = sum((pode_ser_pilha, pode_ser_fila, pode_ser_prioridade))
    if candidatas == 0:
        return "impossible"
    if candidatas > 1:
        return "not sure"
    if pode_ser_pilha:
        return "stack"
    if pode_ser_fila:
        return "queue"
    return "priority queue"


# Os casos aparecem até EOF. Usar um iterador facilita consumir exatamente
# a quantidade de operações declarada em cada caso.
dados = iter(map(int, sys.stdin.buffer.read().split()))

while True:
    try:
        quantidade = next(dados)
    except StopIteration:
        break

    operacoes = [(next(dados), next(dados)) for _ in range(quantidade)]
    print(classificar(operacoes))

import sys


def transformar_sentenca(sentenca):
    """Alterna a caixa das letras sem deixar espaços alterarem o estado."""
    usar_maiuscula = True
    resposta = []

    for caractere in sentenca:
        if caractere.isalpha():
            # O estado determina a caixa desta letra e muda para a próxima.
            resposta.append(
                caractere.upper() if usar_maiuscula else caractere.lower()
            )
            usar_maiuscula = not usar_maiuscula
        else:
            # Espaços e sinais são copiados sem consumir a alternância.
            resposta.append(caractere)

    return "".join(resposta)


def main():
    # O problema fornece sentenças até o fim do arquivo.
    linhas = sys.stdin.buffer.read().decode().splitlines()
    sys.stdout.write("\n".join(map(transformar_sentenca, linhas)) + "\n")


if __name__ == "__main__":
    main()

def circulo_dentro(r1, x1, y1, r2, x2, y2):
    # Um círculo maior nunca cabe no menor.
    if r2 > r1:
        return False

    dx = x1 - x2
    dy = y1 - y2
    limite = r1 - r2

    # Distância entre centros <= diferença dos raios.
    return dx * dx + dy * dy <= limite * limite


def cabem_no_retangulo(largura, altura, r1, r2):
    # Cada diâmetro precisa caber isoladamente.
    for raio in (r1, r2):
        if 2 * raio > largura or 2 * raio > altura:
            return False

    # Cantos opostos maximizam a distância.
    dx = largura - r1 - r2
    dy = altura - r1 - r2
    return dx * dx + dy * dy >= (r1 + r2) ** 2


def main():
    t = int(input())

    for _ in range(t):
        partes = input().split()
        tipo = partes[0]
        valores = list(map(float, partes[1:]))

        if tipo == "DENTRO":
            resposta = circulo_dentro(*valores)
        else:
            resposta = cabem_no_retangulo(*valores)

        print("S" if resposta else "N")


if __name__ == "__main__":
    main()

import math


def areas(lado):
    quadrado = lado * lado
    complemento = quadrado - math.pi * quadrado / 4.0
    segmento = (
        quadrado * (4 * math.pi - 3 * math.sqrt(3)) / 24
    )
    a3 = 8 * segmento + 8 * complemento - 4 * quadrado
    a2 = 4 * complemento - 2 * a3
    a1 = quadrado - a2 - a3
    return a1, a2, a3


def lado_do_quadrado(lado_do_pentagono):
    # math.sin recebe radianos, não graus.
    return (
        lado_do_pentagono
        * math.sin(math.radians(108))
        / math.sin(math.radians(63))
    )


def main():
    t = int(input())

    for _ in range(t):
        tipo, texto = input().split()
        valor = float(texto)

        if tipo == "AREA":
            a1, a2, a3 = areas(valor)
            print(f"{a1:.3f} {a2:.3f} {a3:.3f}")
        else:
            print(f"{lado_do_quadrado(valor):.10f}")


if __name__ == "__main__":
    main()

N, M = 0, 0
mochila = []
blocos = []


def calculaMochila():
    # mochila[j] guarda o menor número de blocos que forma exatamente j.
    mochila = [-1 for _ in range(M + 1)]
    mochila[0] = 0

    for bloco in blocos:
        # O percurso crescente permite reutilizar o mesmo tamanho de bloco.
        for j in range(bloco, M + 1):
            if(mochila[j - bloco] != -1):
                if(mochila[j] == -1):
                    mochila[j] = mochila[j - bloco] + 1
                else:
                    mochila[j] = min(mochila[j], mochila[j - bloco] + 1)

    return mochila[M]


T = int(input())

for _ in range(T):
    N, M = map(int, input().strip().split(' '))
    # Os tamanhos disponíveis formam as transições da programação dinâmica.
    blocos = map(int, input().strip().split(' '))

    print(calculaMochila())
